// Package indexroom implements chain ingestion with reorg handling.
package indexroom

import "sort"

// Block is one ingested block with its transactions.
type Block struct {
	Height int64
	Hash   string
	Parent string
	Txs    []string
}

// Index is the durable chain view.
type Index struct {
	Blocks map[int64]Block
	ByHash map[string]int64
	Tip    int64
}

// New returns an empty index.
func New() *Index { return &Index{Blocks: map[int64]Block{}, ByHash: map[string]int64{}} }

// Append accepts a block only when it extends the current tip, keeping the chain linear.
func (index *Index) Append(block Block) error {
	if block.Height <= 0 || block.Hash == "" {
		return errInvalid("block needs a height and hash")
	}
	if _, exists := index.Blocks[block.Height]; exists {
		return errInvalid("height already indexed")
	}
	if index.Tip != 0 && block.Parent != index.Blocks[index.Tip].Hash {
		return errInvalid("parent does not match the current tip")
	}
	index.Blocks[block.Height] = block
	index.ByHash[block.Hash] = block.Height
	index.Tip = block.Height
	return nil
}

// Reorg replaces the tip range with an alternate branch and reports dropped heights.
func (index *Index) Reorg(blocks []Block) ([]int64, error) {
	if len(blocks) == 0 {
		return nil, errInvalid("empty branch")
	}
	parent, ok := index.ByHash[blocks[0].Parent]
	if !ok {
		return nil, errInvalid("branch parent is unknown")
	}
	var dropped []int64
	for height := parent + 1; height <= index.Tip; height++ {
		dropped = append(dropped, height)
		delete(index.ByHash, index.Blocks[height].Hash)
		delete(index.Blocks, height)
	}
	index.Tip = parent
	for _, block := range blocks {
		if err := index.Append(block); err != nil {
			return dropped, err
		}
	}
	sort.Slice(dropped, func(i, j int) bool { return dropped[i] < dropped[j] })
	return dropped, nil
}

type errInvalid string

func (e errInvalid) Error() string { return string(e) }

// Package indexroom implements chain ingestion with reorg handling.
package indexroom

import (
	"errors"
	"fmt"
	"math"
	"net"
	"sort"
	"strconv"
	"strings"
	"unicode"
)

// Instance is one discoverable service instance.
type Instance struct {
	ID      string
	Address string
}

// HealthState is the offline health observation of one instance.
// Health is driven entirely by submitted observations; no probing occurs.
type HealthState string

// Health states.
const (
	HealthUnknown   HealthState = "unknown"
	HealthHealthy   HealthState = "healthy"
	HealthUnhealthy HealthState = "unhealthy"
)

// InstanceView is a snapshot of one instance together with its health observation.
type InstanceView struct {
	ID       string
	Address  string
	Health   HealthState
	Sequence int64
	Reason   string
}

// Registration is a validated request that replaces a service's instance list.
type Registration struct {
	Service   string
	Revision  int
	Instances []Instance
}

// HealthUpdate is a validated health observation request.
type HealthUpdate struct {
	Service    string
	InstanceID string
	Revision   int
	Sequence   int64
	Healthy    bool
	Reason     string
}

// ServiceView is an immutable snapshot of one registered service.
type ServiceView struct {
	Service   string
	Revision  int
	Instances []InstanceView
}

// OutcomeKind classifies a failed request.
type OutcomeKind string

// Outcome kinds.
const (
	OutcomeInvalid   OutcomeKind = "invalid"
	OutcomeConflict  OutcomeKind = "conflict"
	OutcomeNotFound  OutcomeKind = "not_found"
	OutcomeStale     OutcomeKind = "stale"
	OutcomeNoHealthy OutcomeKind = "no_healthy"
)

// Outcome is the result of applying one registration against the registry.
type Outcome struct {
	Service  string
	OK       bool
	Changed  bool
	Revision int
	Kind     OutcomeKind
	Reason   string
	Expected int
	Actual   int
}

// HealthOutcome is the result of applying one health update against the registry.
type HealthOutcome struct {
	Service    string
	InstanceID string
	OK         bool
	Changed    bool
	Kind       OutcomeKind
	Reason     string
	Revision   int
	Expected   int
	Actual     int
	Sequence   int64
}

// Selection is a validated request that chooses one healthy target instance.
//
// SessionKey is the trimmed session identifier, empty when the request carries
// no session. A non-empty key binds the request to a per-service session: the
// first successful selection remembers the chosen instance for the key and
// later requests with the same key reuse that instance while it stays
// registered and healthy.
type Selection struct {
	Service    string
	Revision   int
	SessionKey string
}

// SelectOutcome is the result of choosing one healthy instance.
//
// On success the chosen instance carries its id, address and current health
// sequence. A selection never mutates registrations, health records, the
// per-service rotation cursor or the session bindings on failure; on success
// it advances that cursor to the chosen instance's id — except when reusing a
// session binding, which leaves the cursor alone — and records the session
// binding when the request carried a session key that went through rotation.
type SelectOutcome struct {
	Service    string
	OK         bool
	Kind       OutcomeKind
	Reason     string
	Revision   int
	Expected   int
	Actual     int
	InstanceID string
	Address    string
	Sequence   int64
}

// SessionRelease is a validated request that drops one session binding.
//
// SessionKey is the trimmed session identifier. The release is scoped to the
// named service only: the same key in another service keeps its binding.
type SessionRelease struct {
	Service    string
	Revision   int
	SessionKey string
}

// ReleaseOutcome is the result of releasing one session binding.
//
// A release never selects a target, so it carries no instance id, address or
// health sequence even on success. Changed is set only when a binding actually
// existed for the key; releasing an unbound key still succeeds with Changed
// left false. The release moves neither the per-service rotation cursor nor
// any binding other than the named one, and it never alters registrations,
// revisions or health records — whether the bound instance was removed, never
// observed healthy or is currently unhealthy does not block removing the
// binding itself.
type ReleaseOutcome struct {
	Service  string
	OK       bool
	Changed  bool
	Kind     OutcomeKind
	Reason   string
	Revision int
	Expected int
	Actual   int
}

// Registry is an in-memory service instance registry.
type Registry struct {
	services map[string]*serviceState
}

type serviceState struct {
	revision  int
	instances map[string]*instanceState // instance id -> state

	// cursor is the id returned by the last successful selection. Selection
	// starts at the smallest healthy id before any success (cursorSet == false)
	// and otherwise continues just after cursor. The cursor intentionally
	// survives registration replacements and health changes: removed instances
	// and recovered or newly joined instances are located by id in the current
	// healthy set without restarting the rotation.
	cursor    string
	cursorSet bool

	// sessions binds a session key to the instance id chosen for it by the
	// key's first successful selection. Bindings live per service, so the same
	// key in two services binds independently. A binding is consulted on every
	// selection carrying its key and is reused only while the instance is still
	// registered and healthy at selection time; otherwise the selection falls
	// back to the normal rotation and the binding is replaced only when that
	// rotation succeeds. Failed selections never create or rewrite a binding.
	sessions map[string]string
}

type instanceState struct {
	address  string
	health   HealthState
	sequence int64
	reason   string
}

// newInstanceState returns a fresh observation: unknown with sequence 0.
func newInstanceState(address string) *instanceState {
	return &instanceState{address: address, health: HealthUnknown}
}

// NewRegistry returns an empty registry.
func NewRegistry() *Registry {
	return &Registry{services: map[string]*serviceState{}}
}

// RevisionOf returns the service's current revision, or 0 when it is unknown.
func (r *Registry) RevisionOf(service string) int {
	if st, ok := r.services[service]; ok {
		return st.revision
	}
	return 0
}

// validateServiceName is the service-identity field shared by every request:
// the trimmed name must not be blank.
func validateServiceName(service string) (string, error) {
	name := strings.TrimSpace(service)
	if name == "" {
		return "", errInvalid("service name must not be empty")
	}
	return name, nil
}

// maxRevision is the largest expectedRevision accepted on the running
// architecture. Revisions are carried by int, so a 32-bit build accepts
// 0..2147483647 and a 64-bit build 0..9223372036854775807. A value outside
// that range must be rejected from its raw submitted form; otherwise it wraps
// when narrowed to int (e.g. 4294967297 becoming 1 on a 32-bit build) and
// could match a revision it never equalled.
const maxRevision = math.MaxInt

// expectedRevisionRangeReason is the invalid reason shared by every request
// kind when a submitted expectedRevision falls outside the architecture's
// integer range. raw carries the submitted digits so the message reports the
// actual value even when it cannot be represented as int or int64.
func expectedRevisionRangeReason(raw string) string {
	return fmt.Sprintf("expectedRevision must be an integer between 0 and %d, got %s", maxRevision, raw)
}

// validateExpectedRevision is the revision field shared by every request. It
// judges the raw submitted value before it is narrowed to int: an int64 still
// holds values outside int's range on a 32-bit build, and converting
// 4294967297 or -4294967295 first would wrap either one into 1, letting a
// mismatching revision look current. A negative value or one above the
// platform's maximum is invalid with a reason stating the expectedRevision
// range. Callers check their remaining content fields around this one, so
// content validity is fully established before any revision comparison
// against the registry.
func validateExpectedRevision(revision int64) error {
	if revision < 0 || revision > maxRevision {
		return errInvalid(expectedRevisionRangeReason(strconv.FormatInt(revision, 10)))
	}
	return nil
}

// ParseExpectedRevision converts the raw decimal text of a submitted
// expectedRevision into an int64 that still carries the submitted value. It
// establishes only the token's integer type: floats, strings, booleans and
// similar text get the integer-type error, while a decimal integer is returned
// without platform-specific narrowing. The architecture range (the 32-bit
// upper bound in particular) is enforced afterwards by
// validateExpectedRevision inside each Validate* method, so the long-standing
// field order (service name, then revision, then the remaining fields) is
// preserved. The one value category that cannot reach that stage is a
// magnitude too large even for int64: ParseInt rejects it with ErrRange and it
// is reported as an expectedRevision range error from its raw text rather than
// an overflowed number.
func ParseExpectedRevision(text string) (int64, error) {
	n, err := strconv.ParseInt(text, 10, 64)
	if err != nil {
		if errors.Is(err, strconv.ErrRange) {
			return 0, errInvalid(expectedRevisionRangeReason(text))
		}
		return 0, errInvalid(fmt.Sprintf("expectedRevision must be an integer, got %s", text))
	}
	return n, nil
}

// sequenceRangeReason is the invalid reason when a submitted sequence cannot
// be carried by int64. raw carries the submitted digits so the message reports
// the actual value even when it cannot be represented, which matters for the
// boundary 9223372036854775808 (one past the maximum) and larger magnitudes.
func sequenceRangeReason(raw string) string {
	return fmt.Sprintf("sequence must be an integer between 1 and %d, got %s", int64(math.MaxInt64), raw)
}

// ParseSequence converts the raw decimal text of a health observation's
// sequence into an int64 that carries the submitted value exactly. It
// establishes only the token's integer type and representability, mirroring
// ParseExpectedRevision: floats, strings, booleans and similar text get the
// integer-type error, and a magnitude too large even for int64 — such as
// 9223372036854775808, one past the signed range — is reported from its raw
// text as a sequence range error rather than an overflowed number. Parsing
// the raw token also keeps a non-integer token from failing the whole item's
// JSON decode: it arrives here as text and becomes that item's own invalid
// result, so later items in the batch still get their per-item outcome. The
// positive-value rule (sequence is per-instance and starts at 1) stays with
// ValidateHealth alongside the other content checks.
func ParseSequence(text string) (int64, error) {
	n, err := strconv.ParseInt(text, 10, 64)
	if err != nil {
		if errors.Is(err, strconv.ErrRange) {
			return 0, errInvalid(sequenceRangeReason(text))
		}
		return 0, errInvalid(fmt.Sprintf("sequence must be an integer, got %s", text))
	}
	return n, nil
}

// revisionFailure describes the common revision-gate result shared by health
// observations and selections. It carries no operation-specific fields: each
// operation maps it onto its own result so stale health sequences, missing
// instances and missing healthy targets never get mixed together.
type revisionFailure struct {
	kind     OutcomeKind
	reason   string
	revision int // current revision (0 for an unknown service)
	expected int
	actual   int
}

// checkServiceRevision applies the gate the health and select operations share.
// Content validation has already happened by the time it runs, so an invalid
// field never reaches it. It first looks the service up (an unknown service is
// at revision 0) and compares revisions: a mismatch is a conflict carrying the
// request's expectedRevision and the actual revision, even when the service or
// the targeted instance is missing. With matching revisions an unknown service
// is not_found; a registered service with an empty instance list is still
// returned, so it compares by its real revision rather than being treated as
// absent. Returning nil means the gate passed and the caller owns the rest.
func (r *Registry) checkServiceRevision(service string, expected int) (*serviceState, *revisionFailure) {
	st, exists := r.services[service]
	actual := 0
	if exists {
		actual = st.revision
	}
	if expected != actual {
		return nil, &revisionFailure{
			kind:     OutcomeConflict,
			reason:   fmt.Sprintf("service %q is at revision %d, not %d", service, actual, expected),
			revision: actual,
			expected: expected,
			actual:   actual,
		}
	}
	if !exists {
		return nil, &revisionFailure{
			kind:     OutcomeNotFound,
			reason:   fmt.Sprintf("service %q does not exist", service),
			revision: 0,
		}
	}
	return st, nil
}

// asHealth maps the shared revision gate failure onto a health result. The
// operation-specific fields (instance id and the current sequence) stay zero so
// they remain omitted exactly as health's own revision failures always have.
func (f *revisionFailure) asHealth(service string) HealthOutcome {
	return HealthOutcome{
		Service:  service,
		OK:       false,
		Kind:     f.kind,
		Reason:   f.reason,
		Revision: f.revision,
		Expected: f.expected,
		Actual:   f.actual,
	}
}

// asSelect maps the shared revision gate failure onto a selection result, which
// never fabricates an instance id, address or sequence on rejection.
func (f *revisionFailure) asSelect(service string) SelectOutcome {
	return SelectOutcome{
		Service:  service,
		OK:       false,
		Kind:     f.kind,
		Reason:   f.reason,
		Revision: f.revision,
		Expected: f.expected,
		Actual:   f.actual,
	}
}

// asRelease maps the shared revision gate failure onto a session-release
// result. It carries no target fields: a release never selects an instance.
func (f *revisionFailure) asRelease(service string) ReleaseOutcome {
	return ReleaseOutcome{
		Service:  service,
		OK:       false,
		Kind:     f.kind,
		Reason:   f.reason,
		Revision: f.revision,
		Expected: f.expected,
		Actual:   f.actual,
	}
}

// ValidateRegistration trims and validates one request without mutating the registry.
// revision is the raw submitted expectedRevision and is range-checked before it
// is narrowed to int. Content validity is established before any revision check.
func (r *Registry) ValidateRegistration(service string, revision int64, instances []Instance) (Registration, error) {
	name, err := validateServiceName(service)
	if err != nil {
		return Registration{}, err
	}
	if err := validateExpectedRevision(revision); err != nil {
		return Registration{}, err
	}
	seen := make(map[string]bool, len(instances))
	valid := make([]Instance, 0, len(instances))
	for _, inst := range instances {
		id := strings.TrimSpace(inst.ID)
		if id == "" {
			return Registration{}, errInvalid("instance id must not be empty")
		}
		if seen[id] {
			return Registration{}, errInvalid(fmt.Sprintf("duplicate instance id %q", id))
		}
		addr, err := parseAddress(inst.Address)
		if err != nil {
			return Registration{}, errInvalid(err.Error())
		}
		seen[id] = true
		valid = append(valid, Instance{ID: id, Address: addr})
	}
	return Registration{Service: name, Revision: int(revision), Instances: valid}, nil
}

// Apply checks the revision and, on match, replaces the service's instance list.
// A new service is created at revision 1 only when expectedRevision is 0.
// A matching registration with identical content succeeds without bumping revision.
func (r *Registry) Apply(reg Registration) Outcome {
	st, exists := r.services[reg.Service]
	if !exists {
		if reg.Revision != 0 {
			return Outcome{
				Service:  reg.Service,
				OK:       false,
				Kind:     OutcomeConflict,
				Reason:   fmt.Sprintf("service %q does not exist yet; expected revision must be 0, got %d", reg.Service, reg.Revision),
				Expected: reg.Revision,
				Actual:   0,
				Revision: 0,
			}
		}
		st = &serviceState{revision: 1, instances: make(map[string]*instanceState, len(reg.Instances))}
		r.services[reg.Service] = st
		for _, inst := range reg.Instances {
			st.instances[inst.ID] = newInstanceState(inst.Address)
		}
		return Outcome{Service: reg.Service, OK: true, Changed: true, Revision: 1}
	}
	if reg.Revision != st.revision {
		return Outcome{
			Service:  reg.Service,
			OK:       false,
			Kind:     OutcomeConflict,
			Reason:   fmt.Sprintf("service %q is at revision %d, not %d", reg.Service, st.revision, reg.Revision),
			Expected: reg.Revision,
			Actual:   st.revision,
			Revision: st.revision,
		}
	}
	changed := !sameInstances(st.instances, reg.Instances)
	if changed {
		// A replacement fully rebuilds the list, but an instance that keeps both
		// its id and its address retains its health observation. Anything new,
		// address-changed, or removed-then-readded starts from unknown at sequence 0.
		next := make(map[string]*instanceState, len(reg.Instances))
		for _, inst := range reg.Instances {
			if old, ok := st.instances[inst.ID]; ok && old.address == inst.Address {
				next[inst.ID] = old
			} else {
				next[inst.ID] = newInstanceState(inst.Address)
			}
		}
		st.instances = next
		st.revision++
	}
	return Outcome{Service: reg.Service, OK: true, Changed: changed, Revision: st.revision}
}

// ValidateHealth trims and validates one health observation without mutating
// the registry. revision is the raw submitted expectedRevision, range-checked
// before it is narrowed to int. Content validity is established before any
// revision check.
func (r *Registry) ValidateHealth(service, instanceID string, revision int64, sequence int64, healthy bool, reason string) (HealthUpdate, error) {
	name, err := validateServiceName(service)
	if err != nil {
		return HealthUpdate{}, err
	}
	id := strings.TrimSpace(instanceID)
	if id == "" {
		return HealthUpdate{}, errInvalid("instance id must not be empty")
	}
	if err := validateExpectedRevision(revision); err != nil {
		return HealthUpdate{}, err
	}
	if sequence <= 0 {
		return HealthUpdate{}, errInvalid("sequence must be a positive integer")
	}
	normalizedReason := strings.TrimSpace(reason)
	if healthy {
		// A healthy observation carries no reason.
		normalizedReason = ""
	} else if normalizedReason == "" {
		return HealthUpdate{}, errInvalid("reason must not be empty when unhealthy")
	}
	return HealthUpdate{
		Service:    name,
		InstanceID: id,
		Revision:   int(revision),
		Sequence:   sequence,
		Healthy:    healthy,
		Reason:     normalizedReason,
	}, nil
}

// ApplyHealth records an offline observation once the shared revision gate has
// passed.
//
// The gate is shared with Select (see checkServiceRevision): a revision
// mismatch is a conflict carrying the request and current revisions even when
// the service or the targeted instance is missing, and a matching request for
// an unknown service is not_found. Only after it does health apply its own
// rules:
//   - a missing instance is not_found;
//   - a sequence below the accepted one is stale and reports the current sequence;
//   - the same sequence with identical normalized status and reason succeeds
//     without changing state;
//   - the same sequence with different content is a conflict;
//   - a newer sequence writes the status and reason.
func (r *Registry) ApplyHealth(upd HealthUpdate) HealthOutcome {
	st, fail := r.checkServiceRevision(upd.Service, upd.Revision)
	if fail != nil {
		return fail.asHealth(upd.Service)
	}
	cur, ok := st.instances[upd.InstanceID]
	if !ok {
		return HealthOutcome{
			Service:    upd.Service,
			InstanceID: upd.InstanceID,
			OK:         false,
			Kind:       OutcomeNotFound,
			Reason:     fmt.Sprintf("instance %q does not exist in service %q", upd.InstanceID, upd.Service),
			Revision:   st.revision,
		}
	}
	if upd.Sequence < cur.sequence {
		return HealthOutcome{
			Service:    upd.Service,
			InstanceID: upd.InstanceID,
			OK:         false,
			Kind:       OutcomeStale,
			Reason:     fmt.Sprintf("sequence %d is older than the current sequence %d", upd.Sequence, cur.sequence),
			Revision:   st.revision,
			Sequence:   cur.sequence,
		}
	}
	if upd.Sequence == cur.sequence {
		want := HealthUnhealthy
		if upd.Healthy {
			want = HealthHealthy
		}
		if cur.health == want && cur.reason == upd.Reason {
			return HealthOutcome{
				Service:    upd.Service,
				InstanceID: upd.InstanceID,
				OK:         true,
				Changed:    false,
				Revision:   st.revision,
				Sequence:   cur.sequence,
			}
		}
		return HealthOutcome{
			Service:    upd.Service,
			InstanceID: upd.InstanceID,
			OK:         false,
			Kind:       OutcomeConflict,
			Reason:     fmt.Sprintf("sequence %d already used with different health content", upd.Sequence),
			Revision:   st.revision,
			Sequence:   cur.sequence,
		}
	}
	// Newer sequence: record the observation. Health updates never bump the
	// registration revision.
	if upd.Healthy {
		cur.health = HealthHealthy
		cur.reason = ""
	} else {
		cur.health = HealthUnhealthy
		cur.reason = upd.Reason
	}
	cur.sequence = upd.Sequence
	return HealthOutcome{
		Service:    upd.Service,
		InstanceID: upd.InstanceID,
		OK:         true,
		Changed:    true,
		Revision:   st.revision,
		Sequence:   cur.sequence,
	}
}

// validateSessionRequest is the content validation shared by select and
// release_session. It trims the service name and range-checks the raw
// expectedRevision before it is narrowed to int, then normalizes the session
// key:
//
//   - a nil key means the field was absent: an ordinary rotating selection is
//     legal for select (keyRequired == false), while release_session rejects
//     it with missingKeyReason because its key is mandatory;
//   - a present key is trimmed; keys equal after trimming name one session
//     within a service, and a blank-after-trim key is invalid with a reason
//     naming the sessionKey problem.
//
// The order mirrors every other request kind — service name, then the
// revision range, then the remaining content field — so content validity is
// fully established before any revision comparison against the registry.
// Null and non-string key tokens are a JSON concern handled by callers before
// this helper runs and never arrive here as a *string.
func validateSessionRequest(service string, revision int64, sessionKey *string, keyRequired bool, missingKeyReason string) (name string, rev int, key string, err error) {
	name, err = validateServiceName(service)
	if err != nil {
		return "", 0, "", err
	}
	if err = validateExpectedRevision(revision); err != nil {
		return "", 0, "", err
	}
	if sessionKey == nil {
		if keyRequired {
			return "", 0, "", errInvalid(missingKeyReason)
		}
		return name, int(revision), "", nil
	}
	key = strings.TrimSpace(*sessionKey)
	if key == "" {
		return "", 0, "", errInvalid("sessionKey must not be empty")
	}
	return name, int(revision), key, nil
}

// ValidateSelection trims and validates one select request without touching
// the registry. Content validity is established before any revision check.
func (r *Registry) ValidateSelection(service string, revision int64) (Selection, error) {
	return r.ValidateSelectionWithSession(service, revision, nil)
}

// ValidateSelectionWithSession is ValidateSelection with an optional session
// key. A nil key means an ordinary rotating selection. A non-nil key is
// trimmed and must not be blank: keys that differ only in surrounding
// whitespace name the same session. revision is the raw submitted
// expectedRevision, range-checked before it is narrowed to int. Content
// validity is established before any revision check.
func (r *Registry) ValidateSelectionWithSession(service string, revision int64, sessionKey *string) (Selection, error) {
	name, rev, key, err := validateSessionRequest(service, revision, sessionKey, false, "")
	if err != nil {
		return Selection{}, err
	}
	return Selection{Service: name, Revision: rev, SessionKey: key}, nil
}

// ValidateSessionRelease trims and validates one release_session request
// without touching the registry. Unlike a selection the sessionKey is
// mandatory: a nil (absent) key or a blank-after-trim key is invalid with a
// reason naming the sessionKey problem. revision is the raw submitted
// expectedRevision, range-checked before it is narrowed to int. The check
// order mirrors ValidateSelectionWithSession — service name, then the
// revision range, then the key — and content validity is fully established
// before any revision comparison against the registry.
func (r *Registry) ValidateSessionRelease(service string, revision int64, sessionKey *string) (SessionRelease, error) {
	const missingKeyReason = "sessionKey is required and must be a non-empty string"
	name, rev, key, err := validateSessionRequest(service, revision, sessionKey, true, missingKeyReason)
	if err != nil {
		return SessionRelease{}, err
	}
	return SessionRelease{Service: name, Revision: rev, SessionKey: key}, nil
}

// Select chooses one healthy instance for the service once the shared revision
// gate has passed.
//
// The gate is shared with ApplyHealth (see checkServiceRevision): a mismatch is
// a conflict carrying the request and current revisions (an unknown service is
// at revision 0), and a matching request for an unknown service is not_found.
// Only after it does select apply its own rule: an existing service with no
// healthy instance is no_healthy and no address is fabricated. A registered
// service with an empty instance list still compares by its real revision; the
// gate hands it through so the answer is no_healthy, not not_found.
//
// Healthy instances rotate per service by ascending instance id: the first
// success takes the smallest id and each later success continues just after
// the previously chosen id, wrapping to the smallest id past the end. With a
// single healthy instance it may be chosen repeatedly. Registrations and
// health changes alter the candidate set immediately but never reset the
// rotation; failed selections leave the cursor where it was.
//
// A request carrying a session key is sticky: while the key's bound instance
// is still registered and healthy at selection time, it is returned with its
// current address and latest accepted health sequence, and the rotation
// cursor does not move. A binding that points at a removed, unknown or
// unhealthy instance is ignored — an instance whose id survived an address
// change is unknown until a fresh observation at the new address, so its old
// health record never carries over — and the request falls back to the normal
// rotation, which on success advances the cursor and replaces the binding.
// The first selection for a key behaves exactly like an ordinary rotation
// success and additionally records the binding. Failed selections (including
// no_healthy) create no binding, rewrite none and move no cursor.
func (r *Registry) Select(sel Selection) SelectOutcome {
	st, fail := r.checkServiceRevision(sel.Service, sel.Revision)
	if fail != nil {
		return fail.asSelect(sel.Service)
	}

	// A bound session reuses its instance while it is registered and healthy;
	// the reuse reflects the instance's current address and sequence and does
	// not advance the rotation.
	if sel.SessionKey != "" {
		if id, bound := st.sessions[sel.SessionKey]; bound {
			if cur, ok := st.instances[id]; ok && cur.health == HealthHealthy {
				return SelectOutcome{
					Service:    sel.Service,
					OK:         true,
					Revision:   st.revision,
					InstanceID: id,
					Address:    cur.address,
					Sequence:   cur.sequence,
				}
			}
		}
	}

	healthy := make([]string, 0, len(st.instances))
	for id, cur := range st.instances {
		if cur.health == HealthHealthy {
			healthy = append(healthy, id)
		}
	}
	sort.Strings(healthy)
	if len(healthy) == 0 {
		return SelectOutcome{
			Service:  sel.Service,
			OK:       false,
			Kind:     OutcomeNoHealthy,
			Reason:   fmt.Sprintf("service %q has no healthy instance available", sel.Service),
			Revision: st.revision,
		}
	}

	chosen := healthy[0]
	if st.cursorSet {
		chosen = healthy[0]
		for _, id := range healthy {
			if id > st.cursor {
				chosen = id
				break
			}
		}
	}
	cur := st.instances[chosen]
	st.cursor = chosen
	st.cursorSet = true
	if sel.SessionKey != "" {
		if st.sessions == nil {
			st.sessions = make(map[string]string)
		}
		st.sessions[sel.SessionKey] = chosen
	}
	return SelectOutcome{
		Service:    sel.Service,
		OK:         true,
		Revision:   st.revision,
		InstanceID: chosen,
		Address:    cur.address,
		Sequence:   cur.sequence,
	}
}

// ReleaseSession drops one session binding once the shared revision gate has
// passed.
//
// The gate is the same one health and select use (see
// checkServiceRevision): a revision mismatch is a conflict carrying the
// request and current revisions (an unknown service is at revision 0), and a
// matching request for an unknown service is not_found — including when
// expectedRevision is 0. Only after it does release do its own work.
//
// Releasing deletes at most the named key's binding in the named service. It
// never consults the bound instance's state: whether that instance was
// removed, never observed healthy, is currently unknown/unhealthy, or the
// service's instance list is empty cannot keep the binding in place, since
// the binding is only a remembered id. Releasing a key that has no binding
// still succeeds with Changed left false. No target is chosen, so the result
// carries no instance id, address or health sequence.
//
// The release moves and resets neither the rotation cursor nor any other
// session's binding (including another session bound to the same instance and
// the same key in another service), and it never alters the instance list,
// the registration revision or a health record. The next selection with the
// released key follows the first-binding rule: it rotates from just after the
// last actually rotated position and records a fresh binding only on success.
func (r *Registry) ReleaseSession(rel SessionRelease) ReleaseOutcome {
	st, fail := r.checkServiceRevision(rel.Service, rel.Revision)
	if fail != nil {
		return fail.asRelease(rel.Service)
	}
	_, bound := st.sessions[rel.SessionKey]
	if bound {
		delete(st.sessions, rel.SessionKey)
	}
	return ReleaseOutcome{
		Service:  rel.Service,
		OK:       true,
		Changed:  bound,
		Revision: st.revision,
	}
}

// Snapshot returns all services sorted by name, with instances sorted by id.
func (r *Registry) Snapshot() []ServiceView {
	names := make([]string, 0, len(r.services))
	for name := range r.services {
		names = append(names, name)
	}
	sort.Strings(names)
	views := make([]ServiceView, 0, len(names))
	for _, name := range names {
		st := r.services[name]
		ids := make([]string, 0, len(st.instances))
		for id := range st.instances {
			ids = append(ids, id)
		}
		sort.Strings(ids)
		instances := make([]InstanceView, 0, len(ids))
		for _, id := range ids {
			cur := st.instances[id]
			instances = append(instances, InstanceView{
				ID:       id,
				Address:  cur.address,
				Health:   cur.health,
				Sequence: cur.sequence,
				Reason:   cur.reason,
			})
		}
		views = append(views, ServiceView{Service: name, Revision: st.revision, Instances: instances})
	}
	return views
}

func sameInstances(current map[string]*instanceState, incoming []Instance) bool {
	if len(current) != len(incoming) {
		return false
	}
	for _, inst := range incoming {
		if old, ok := current[inst.ID]; !ok || old.address != inst.Address {
			return false
		}
	}
	return true
}

// parseAddress validates a host:port address: domains, IPv4 and bracketed IPv6.
// No network I/O is performed.
func parseAddress(raw string) (string, error) {
	addr := strings.TrimSpace(raw)
	if addr == "" {
		return "", fmt.Errorf("instance address must not be empty")
	}
	for _, r := range addr {
		if unicode.IsSpace(r) || unicode.IsControl(r) {
			return "", fmt.Errorf("instance address %q must not contain whitespace or control characters", addr)
		}
	}
	host, port, err := net.SplitHostPort(addr)
	if err != nil {
		return "", fmt.Errorf("instance address %q is not a host:port address: %v", addr, err)
	}
	if host == "" {
		return "", fmt.Errorf("instance address %q has an empty host", addr)
	}
	if !allDigits(port) {
		return "", fmt.Errorf("instance address %q port %q must be a decimal integer", addr, port)
	}
	n, err := strconv.Atoi(port)
	if err != nil {
		return "", fmt.Errorf("instance address %q port %q must be a decimal integer", addr, port)
	}
	if n < 1 || n > 65535 {
		return "", fmt.Errorf("instance address %q port %d is out of range (1-65535)", addr, n)
	}
	if strings.HasPrefix(addr, "[") {
		ip := net.ParseIP(host)
		if ip == nil || !strings.Contains(host, ":") {
			return "", fmt.Errorf("instance address %q bracketed host is not a valid IPv6 address", addr)
		}
	} else if ip := net.ParseIP(host); ip != nil {
		if ip.To4() == nil {
			return "", fmt.Errorf("instance address %q IPv6 addresses must be bracketed", addr)
		}
	} else if !isDomainName(host) {
		return "", fmt.Errorf("instance address %q host %q is not a valid domain, IPv4 or bracketed IPv6", addr, host)
	}
	return addr, nil
}

func allDigits(s string) bool {
	if s == "" {
		return false
	}
	for _, r := range s {
		if r < '0' || r > '9' {
			return false
		}
	}
	return true
}

// isDomainName validates a dotted hostname with alphanumeric/hyphen labels.
func isDomainName(host string) bool {
	if len(host) > 253 {
		return false
	}
	for _, label := range strings.Split(host, ".") {
		n := len(label)
		if n == 0 || n > 63 {
			return false
		}
		if label[0] == '-' || label[n-1] == '-' {
			return false
		}
		for _, r := range label {
			if r == '-' ||
				(r >= 'a' && r <= 'z') ||
				(r >= 'A' && r <= 'Z') ||
				(r >= '0' && r <= '9') {
				continue
			}
			return false
		}
	}
	return true
}

// Command indexroom is the 链上索引与交易分析服务 entry point.
package main

import (
	"encoding/json"
	"fmt"
	"io"
	"os"
	"strings"

	"github.com/gzhysuiioo/indexroom-analytics/indexroom"
)

func main() {
	command := "demo"
	if len(os.Args) > 1 {
		command = os.Args[1]
	}
	switch command {
	case "demo":
		runDemo()
	case "version":
		fmt.Println("indexroom 0.1.0")
	case "register":
		// register reports result-delivery failures via its exit status and
		// stderr; a broken standard output must surface as an EPIPE write error,
		// not as the default SIGPIPE termination.
		ignoreSigpipe()
		os.Exit(runRegister())
	case "help", "-h", "--help":
		usage()
	default:
		fmt.Fprintf(os.Stderr, "unknown command %q\n", command)
		usage()
		os.Exit(2)
	}
}

func usage() {
	fmt.Println("usage: indexroom [demo|version|register|help]")
	fmt.Println()
	fmt.Println("register reads requests as JSON from standard input and maintains an")
	fmt.Println("in-memory service instance registry with offline health observations:")
	fmt.Println(`  {"requests":[{"type":"register","service":"svc","expectedRevision":0,"instances":[{"id":"i1","address":"host:8080"}]},`)
	fmt.Println(`              {"type":"health","service":"svc","instanceId":"i1","expectedRevision":1,"sequence":1,"healthy":true},`)
	fmt.Println(`              {"type":"select","service":"svc","expectedRevision":1},`)
	fmt.Println(`              {"type":"release_session","service":"svc","expectedRevision":1,"sessionKey":"user-42"}]}`)
	fmt.Println("A register request fully replaces the service's instance list; new services")
	fmt.Println("require expectedRevision 0, existing services the current revision. A health")
	fmt.Println("request records an offline observation (healthy/unhealthy) for one instance;")
	fmt.Println("it never probes. Health updates never bump the registration revision. A")
	fmt.Println("select request chooses one healthy instance, rotating per service by ascending")
	fmt.Println("instance id; it performs no network access and never changes revisions or")
	fmt.Println("health records, and reports invalid/conflict/not_found/no_healthy on failure.")
	fmt.Println("A select request may carry an optional \"sessionKey\" string: requests in the")
	fmt.Println("same service with the same trimmed key reuse the instance first chosen for")
	fmt.Println("that key while it stays registered and healthy, without moving the rotation.")
	fmt.Println("A release_session request carries service, expectedRevision and a required")
	fmt.Println("sessionKey; it drops that key's binding in the named service so the next")
	fmt.Println("selection with the key joins the rotation again. It chooses no target, moves")
	fmt.Println("no cursor, and succeeds without changed when the key has no binding.")
	fmt.Println("Exit status is 0 only when every request succeeds and the JSON result")
	fmt.Println("is fully written to standard output. A failed result write is reported")
	fmt.Println("on standard error with the underlying write error and also exits 1,")
	fmt.Println("without appending a second JSON document to the partial output.")
}

// registerInstance is one instance in the final service list.
type registerInstance struct {
	ID       string `json:"id"`
	Address  string `json:"address"`
	Health   string `json:"health"`
	Sequence int64  `json:"sequence"`
	Reason   string `json:"reason,omitempty"`
}

// registerService is one service in the final service list.
type registerService struct {
	Service   string             `json:"service"`
	Revision  int                `json:"revision"`
	Instances []registerInstance `json:"instances"`
}

// registerResult is the per-item outcome.
type registerResult struct {
	Service          string `json:"service"`
	OK               bool   `json:"ok"`
	Changed          bool   `json:"changed,omitempty"`
	Revision         int    `json:"revision"`
	Error            string `json:"error,omitempty"`
	Reason           string `json:"reason,omitempty"`
	ExpectedRevision int    `json:"expectedRevision,omitempty"`
	ActualRevision   int    `json:"actualRevision,omitempty"`
	Sequence         int64  `json:"sequence,omitempty"`
	InstanceID       string `json:"instanceId,omitempty"`
	Address          string `json:"address,omitempty"`
}

// registerOutput is the full register output.
type registerOutput struct {
	Results  []registerResult  `json:"results"`
	Services []registerService `json:"services"`
}

// runRegister processes registration requests from the process standard
// streams. It returns the process exit code: 0 when all registrations succeed
// and the result is fully written, 1 otherwise.
func runRegister() int {
	return runRegisterIO(os.Stdin, os.Stdout, os.Stderr)
}

// runRegisterIO is runRegister with injectable streams. in supplies the JSON
// request batch, out receives the single JSON result document and errOut
// receives diagnostics (in particular a result-delivery failure, which must
// never be mixed into out).
func runRegisterIO(in io.Reader, out io.Writer, errOut io.Writer) int {
	data, err := io.ReadAll(in)
	if err != nil {
		return failRegister(out, errOut, fmt.Sprintf("could not read standard input: %v", err))
	}

	var top struct {
		Requests json.RawMessage `json:"requests"`
	}
	if err := json.Unmarshal(data, &top); err != nil {
		return failRegister(out, errOut, fmt.Sprintf("input must be a JSON object with a requests array: %v", err))
	}
	if len(top.Requests) == 0 || strings.TrimSpace(string(top.Requests)) == "null" {
		return failRegister(out, errOut, "input must contain a \"requests\" array")
	}
	var rawRequests []json.RawMessage
	if err := json.Unmarshal(top.Requests, &rawRequests); err != nil {
		return failRegister(out, errOut, "\"requests\" must be a JSON array")
	}

	proc := &registerProcessor{
		registry: indexroom.NewRegistry(),
		results:  make([]registerResult, 0, len(rawRequests)),
	}

	for _, raw := range rawRequests {
		var head struct {
			Service string          `json:"service"`
			Type    json.RawMessage `json:"type"`
		}
		_ = json.Unmarshal(raw, &head)
		service := strings.TrimSpace(head.Service)

		reqType := "register"
		if len(head.Type) > 0 && strings.TrimSpace(string(head.Type)) != "null" {
			var t string
			if err := json.Unmarshal(head.Type, &t); err != nil {
				proc.invalid(service, "type must be a string")
				continue
			}
			reqType = t
		}

		switch reqType {
		case "", "register":
			proc.registerRequest(raw, service)
		case "health":
			proc.healthRequest(raw, service)
		case "select":
			proc.selectRequest(raw, service)
		case "release_session":
			proc.releaseSessionRequest(raw, service)
		default:
			proc.invalidf(service, "unknown type %q", reqType)
		}
	}

	results, anyFailed := proc.results, proc.failed
	registry := proc.registry

	services := make([]registerService, 0)
	for _, view := range registry.Snapshot() {
		insts := make([]registerInstance, 0, len(view.Instances))
		for _, inst := range view.Instances {
			insts = append(insts, registerInstance{
				ID:       inst.ID,
				Address:  inst.Address,
				Health:   string(inst.Health),
				Sequence: inst.Sequence,
				Reason:   inst.Reason,
			})
		}
		services = append(services, registerService{
			Service:   view.Service,
			Revision:  view.Revision,
			Instances: insts,
		})
	}

	if err := writeRegisterOutput(out, registerOutput{Results: results, Services: services}); err != nil {
		// The request results could not be delivered. This is independent of
		// whether the requests themselves succeeded: the caller must be able to
		// tell an undelivered result from a rejected request.
		reportRegisterDeliveryFailure(errOut, err)
		return 1
	}
	if anyFailed {
		return 1
	}
	return 0
}

// registerProcessor runs the request batch in input order. Failed items keep
// their slot in results and set failed; later items still run against the
// state committed by earlier successful items.
type registerProcessor struct {
	registry *indexroom.Registry
	results  []registerResult
	failed   bool
}

// invalid records an input-validation failure for an item. Content validity is
// checked before any business rule, so the revision stamped here is the
// service's current revision when the item is handled.
func (p *registerProcessor) invalid(service, reason string) {
	p.failed = true
	p.results = append(p.results, registerResult{
		Service:  service,
		OK:       false,
		Error:    "invalid",
		Reason:   reason,
		Revision: p.registry.RevisionOf(service),
	})
}

// invalidf is invalid with a formatted reason.
func (p *registerProcessor) invalidf(service, format string, args ...any) {
	p.invalid(service, fmt.Sprintf(format, args...))
}

// revisionMissing reports whether a raw expectedRevision token is absent or
// explicitly null; both report the shared required-field error.
func revisionMissing(raw json.RawMessage) bool {
	return len(raw) == 0 || strings.TrimSpace(string(raw)) == "null"
}

// parseRevision decodes the raw expectedRevision token for one request. An
// absent or explicitly null token is "required"; a token that is not a decimal
// integer is an integer-type invalid. A decimal integer is returned as int64 —
// still carrying the submitted value — so the registry can range-check it
// against the architecture (0..2147483647 on 32-bit, 0..9223372036854775807
// on 64-bit) before it is narrowed to int; narrowing first would wrap values
// like 4294967297 into 1 on a 32-bit build. It reports false after appending
// the item's invalid result, which stamps the service's current revision.
// Every request kind shares this check, so the missing/null reason and its
// precedence live here rather than at each call site.
func (p *registerProcessor) parseRevision(service string, raw json.RawMessage) (int64, bool) {
	if revisionMissing(raw) {
		p.invalid(service, "expectedRevision is required and must be a non-negative integer")
		return 0, false
	}
	revision, err := indexroom.ParseExpectedRevision(string(raw))
	if err != nil {
		p.invalid(service, err.Error())
		return 0, false
	}
	return revision, true
}

// parseSequence decodes the raw sequence token for one health observation. A
// decimal integer is returned as int64 carrying the submitted value exactly;
// a non-integer token (a float, string or boolean) and a magnitude outside
// the signed int64 range — including 9223372036854775808, one past the
// maximum — become that item's own invalid result with a reason naming the
// sequence problem, instead of failing the whole item's JSON decode with a
// Go-level unmarshal error. Reading the token raw is what keeps the batch
// per-item: one out-of-range sequence neither aborts the batch nor steals the
// outcomes of later items. The positive-value rule is enforced afterwards by
// the registry's ValidateHealth, alongside its other content checks.
func (p *registerProcessor) parseSequence(service string, raw json.RawMessage) (int64, bool) {
	sequence, err := indexroom.ParseSequence(string(raw))
	if err != nil {
		p.invalid(service, err.Error())
		return 0, false
	}
	return sequence, true
}

// sessionRequestInput is the decoded content shared by select and
// release_session requests: the trimmed service name, the parsed
// expectedRevision (still int64, range-checked later by the registry before it
// is narrowed to int), and the optional session key (nil when the field was
// omitted). Explicit null and non-string keys are rejected while decoding.
type sessionRequestInput struct {
	service    string
	revision   int64
	sessionKey *string
}

// readSessionRequest decodes one select/release_session item, centralizing the
// input handling the two request kinds repeat. shapeReason is the operation's
// format string for a malformed object (it consumes the decode error).
//
// The field order is the one every request kind keeps: a missing or null
// expectedRevision is the required-field error first; once the revision token
// is present, an explicit null or a non-string sessionKey is the sessionKey
// type error (never "no key submitted"), and only then is the revision parsed
// as an integer. An omitted sessionKey arrives as nil: select's validator
// treats it as an ordinary rotating selection, while release_session's
// validator rejects it as a sessionKey problem — each after the service-name
// and revision-range checks, so a simultaneously bad revision still precedes
// it. A present string key is trimmed by the registry's shared validator
// together with that range check: keys equal after trimming name one session
// and a blank-after-trim key loses to nothing but a service-name or
// revision-range problem. On failure the item's invalid result is appended and
// ok is false; on success the caller validates against the registry and maps
// its own business outcome.
func (p *registerProcessor) readSessionRequest(raw json.RawMessage, service, shapeReason string) (sessionRequestInput, bool) {
	var req struct {
		Service  string          `json:"service"`
		Revision json.RawMessage `json:"expectedRevision"`
		Session  json.RawMessage `json:"sessionKey"`
	}
	if err := json.Unmarshal(raw, &req); err != nil {
		p.invalidf(service, shapeReason, err)
		return sessionRequestInput{}, false
	}
	service = strings.TrimSpace(req.Service)

	if revisionMissing(req.Revision) {
		p.invalid(service, "expectedRevision is required and must be a non-negative integer")
		return sessionRequestInput{}, false
	}

	// An explicit null or a non-string token names a sessionKey type problem
	// for either request kind; it is judged once the revision token is known
	// present and before the revision is parsed. An omitted field stays nil and
	// reaches the operation's own validator, which distinguishes an ordinary
	// keyless select from release_session's mandatory key.
	var sessionKey *string
	if len(req.Session) > 0 {
		if strings.TrimSpace(string(req.Session)) == "null" {
			p.invalid(service, "sessionKey must be a string, not null")
			return sessionRequestInput{}, false
		}
		var key string
		if err := json.Unmarshal(req.Session, &key); err != nil {
			p.invalid(service, "sessionKey must be a string")
			return sessionRequestInput{}, false
		}
		sessionKey = &key
	}

	revision, ok := p.parseRevision(service, req.Revision)
	if !ok {
		return sessionRequestInput{}, false
	}
	return sessionRequestInput{service: service, revision: revision, sessionKey: sessionKey}, true
}

// reject records a business-rule failure (conflict, not_found, stale or
// no_healthy), keeping each operation's distinct result fields. Health
// rejections additionally carry the current sequence; register and select
// pass 0 so it stays omitted.
func (p *registerProcessor) reject(service string, kind indexroom.OutcomeKind, reason string, revision, expected, actual int, sequence int64) {
	p.failed = true
	p.results = append(p.results, registerResult{
		Service:          service,
		OK:               false,
		Error:            string(kind),
		Reason:           reason,
		Revision:         revision,
		ExpectedRevision: expected,
		ActualRevision:   actual,
		Sequence:         sequence,
	})
}

// succeed records an accepted item; omitempty keeps zero-valued fields out of
// the output exactly as before the refactor.
func (p *registerProcessor) succeed(result registerResult) {
	result.OK = true
	p.results = append(p.results, result)
}

// registerRequest processes one register request, appending its outcome.
func (p *registerProcessor) registerRequest(raw json.RawMessage, service string) {
	var req struct {
		Service   string          `json:"service"`
		Revision  json.RawMessage `json:"expectedRevision"`
		Instances json.RawMessage `json:"instances"`
	}
	if err := json.Unmarshal(raw, &req); err != nil {
		p.invalidf(service, "request must be an object with service, expectedRevision and instances: %v", err)
		return
	}
	service = strings.TrimSpace(req.Service)

	if revisionMissing(req.Revision) {
		p.invalid(service, "expectedRevision is required and must be a non-negative integer")
		return
	}
	if !isJSONArray(req.Instances) {
		p.invalid(service, "instances must be an array")
		return
	}
	var instances []indexroom.Instance
	if err := json.Unmarshal(req.Instances, &instances); err != nil {
		p.invalidf(service, "instances must be an array of objects with id and address: %v", err)
		return
	}

	// Parse the raw token (integer type); ValidateRegistration then range-checks
	// the int64 against the architecture before narrowing it to int.
	revision, ok := p.parseRevision(service, req.Revision)
	if !ok {
		return
	}
	registration, err := p.registry.ValidateRegistration(service, revision, instances)
	if err != nil {
		p.invalid(service, err.Error())
		return
	}

	outcome := p.registry.Apply(registration)
	if !outcome.OK {
		p.reject(outcome.Service, outcome.Kind, outcome.Reason, outcome.Revision, outcome.Expected, outcome.Actual, 0)
		return
	}
	p.succeed(registerResult{
		Service:  outcome.Service,
		Changed:  outcome.Changed,
		Revision: outcome.Revision,
	})
}

// healthRequest processes one health observation request, appending its outcome.
func (p *registerProcessor) healthRequest(raw json.RawMessage, service string) {
	var req struct {
		Service    string          `json:"service"`
		InstanceID string          `json:"instanceId"`
		Revision   json.RawMessage `json:"expectedRevision"`
		Sequence   json.RawMessage `json:"sequence"`
		Healthy    *bool           `json:"healthy"`
		Reason     *string         `json:"reason"`
	}
	if err := json.Unmarshal(raw, &req); err != nil {
		p.invalidf(service, "health request must be an object with service, instanceId, expectedRevision, sequence and healthy: %v", err)
		return
	}
	service = strings.TrimSpace(req.Service)

	if revisionMissing(req.Revision) {
		p.invalid(service, "expectedRevision is required and must be a non-negative integer")
		return
	}
	if len(req.Sequence) == 0 || strings.TrimSpace(string(req.Sequence)) == "null" {
		p.invalid(service, "sequence is required and must be a positive integer")
		return
	}
	if req.Healthy == nil {
		p.invalid(service, "healthy is required and must be a boolean")
		return
	}
	reason := ""
	if req.Reason != nil {
		reason = *req.Reason
	}

	// Parse the raw tokens (integer type); ValidateHealth then range-checks
	// the revision against the architecture before narrowing it to int, while
	// a non-integer or out-of-range sequence becomes this item's own invalid
	// result carrying a sequence-specific reason rather than a decode error.
	revision, ok := p.parseRevision(service, req.Revision)
	if !ok {
		return
	}
	sequence, ok := p.parseSequence(service, req.Sequence)
	if !ok {
		return
	}
	update, err := p.registry.ValidateHealth(service, req.InstanceID, revision, sequence, *req.Healthy, reason)
	if err != nil {
		p.invalid(service, err.Error())
		return
	}

	outcome := p.registry.ApplyHealth(update)
	if !outcome.OK {
		p.reject(outcome.Service, outcome.Kind, outcome.Reason, outcome.Revision, outcome.Expected, outcome.Actual, outcome.Sequence)
		return
	}
	p.succeed(registerResult{
		Service:  outcome.Service,
		Changed:  outcome.Changed,
		Revision: outcome.Revision,
		Sequence: outcome.Sequence,
	})
}

// selectRequest processes one select request, appending its outcome.
// A selection performs no network access and never alters registrations or
// health records; it only advances the service's healthy-instance rotation
// and, for requests carrying a sessionKey, maintains that session's binding.
func (p *registerProcessor) selectRequest(raw json.RawMessage, service string) {
	in, ok := p.readSessionRequest(raw, service,
		"select request must be an object with service and expectedRevision: %v")
	if !ok {
		return
	}

	// readSessionRequest delivered the parsed revision and the key as decoded
	// (nil for an omitted key); ValidateSelectionWithSession repeats the shared
	// service/revision/key content checks via the registry and trims the key.
	selection, err := p.registry.ValidateSelectionWithSession(in.service, in.revision, in.sessionKey)
	if err != nil {
		p.invalid(in.service, err.Error())
		return
	}

	outcome := p.registry.Select(selection)
	if !outcome.OK {
		p.reject(outcome.Service, outcome.Kind, outcome.Reason, outcome.Revision, outcome.Expected, outcome.Actual, 0)
		return
	}
	p.succeed(registerResult{
		Service:    outcome.Service,
		Revision:   outcome.Revision,
		InstanceID: outcome.InstanceID,
		Address:    outcome.Address,
		Sequence:   outcome.Sequence,
	})
}

// releaseSessionRequest processes one release_session request, appending its
// outcome. The request releases one session binding in one service: it never
// selects a target, never moves the rotation cursor or any other binding, and
// never alters the instance list, revision or health records. A present
// binding is removed and reported changed; releasing an unbound key still
// succeeds without changed.
func (p *registerProcessor) releaseSessionRequest(raw json.RawMessage, service string) {
	in, ok := p.readSessionRequest(raw, service,
		"release_session request must be an object with service, expectedRevision and sessionKey: %v")
	if !ok {
		return
	}

	// The key is mandatory for release: readSessionRequest rejects an explicit
	// null or non-string key, and an omitted key reaches ValidateSessionRelease
	// as nil and is rejected there after the service-name and revision-range
	// checks. The validator also trims the key and rejects a blank one before
	// any revision comparison against the registry.
	release, err := p.registry.ValidateSessionRelease(in.service, in.revision, in.sessionKey)
	if err != nil {
		p.invalid(in.service, err.Error())
		return
	}

	outcome := p.registry.ReleaseSession(release)
	if !outcome.OK {
		p.reject(outcome.Service, outcome.Kind, outcome.Reason, outcome.Revision, outcome.Expected, outcome.Actual, 0)
		return
	}
	p.succeed(registerResult{
		Service:  outcome.Service,
		Changed:  outcome.Changed,
		Revision: outcome.Revision,
	})
}

// failRegister emits a top-level input error as the single JSON document on
// out and returns exit code 1. If that error JSON itself cannot be written,
// the delivery failure is diagnosed on errOut (out may already hold a partial
// document, so no second JSON is appended) and the exit code stays 1.
func failRegister(out io.Writer, errOut io.Writer, reason string) int {
	if err := writeRegisterOutput(out, struct {
		Error string `json:"error"`
	}{Error: reason}); err != nil {
		reportRegisterDeliveryFailure(errOut, err)
	}
	return 1
}

// reportRegisterDeliveryFailure reports on errOut that the register command's
// JSON result could not be delivered, preserving the underlying write error.
// It never writes to standard output, which may already contain a partial
// result.
func reportRegisterDeliveryFailure(errOut io.Writer, err error) {
	fmt.Fprintf(errOut, "register: failed to write request results to standard output: %v\n", err)
}

// writeRegisterOutput writes v as the single indented JSON document on w.
// Standard output is dedicated to this document, so a write failure is returned
// instead of swallowed: the caller must not attempt to append another document
// after a partial write.
func writeRegisterOutput(w io.Writer, v any) error {
	enc := json.NewEncoder(w)
	enc.SetIndent("", "  ")
	return enc.Encode(v)
}

// isJSONArray reports whether raw is a JSON array (ignoring leading whitespace).
func isJSONArray(raw json.RawMessage) bool {
	for _, b := range raw {
		switch b {
		case ' ', '\t', '\n', '\r':
			continue
		case '[':
			return true
		default:
			return false
		}
	}
	return false
}

func runDemo() {
	index := indexroom.New()
	blocks := []indexroom.Block{
		{Height: 1, Hash: "h1", Parent: "genesis", Txs: []string{"t1", "t2"}},
		{Height: 2, Hash: "h2", Parent: "h1", Txs: []string{"t3"}},
	}
	for _, block := range blocks {
		if err := index.Append(block); err != nil {
			fmt.Printf("append refused at height %d: %v\n", block.Height, err)
			continue
		}
		fmt.Printf("indexed height=%d txs=%d\n", block.Height, len(block.Txs))
	}
	if err := index.Append(indexroom.Block{Height: 3, Hash: "h3", Parent: "h1"}); err != nil {
		fmt.Println("non-linear block refused:", err)
	}
	dropped, err := index.Reorg([]indexroom.Block{{Height: 2, Hash: "h2b", Parent: "h1", Txs: []string{"t4", "t5"}}})
	fmt.Printf("reorg dropped=%v err=%v tip=%d\n", dropped, err, index.Tip)
}

package indexroom

import "testing"

// This file is the regression guard for several session keys interleaved
// against ONE service. The per-service session map already binds each trimmed
// key independently, but the earlier suite only exercised a single key per
// service (or the same key in different services). These tests lock the
// cross-session guarantees purely through the public registration, health and
// selection results:
//
//   - two distinct keys first succeed by consuming the same rotation in turn,
//     each remembering its own instance; an existing binding never chooses the
//     target for a new key;
//   - interleaved keyed reuses return each session's own current binding
//     (id, address and latest accepted health sequence) without moving the
//     shared rotation, and plain selects continue from the last real rotation;
//   - when one key's bound instance turns unhealthy, only that key's binding is
//     rewritten by a fallback rotation, and two keys may legitimately bind to
//     the same instance without stealing each other's binding;
//   - an all-unhealthy no_healthy failure fabricates no target and preserves
//     both sessions' bindings and the rotation position.
//
// No session query, release or expiry operation exists or is introduced: the
// bindings are observed only through what later selections return.

// selectSession validates and runs one select carrying a session key,
// returning the outcome (success or failure) so failure cases can be asserted
// directly instead of failing the helper.
func selectSession(t *testing.T, r *Registry, service string, revision int64, key string) SelectOutcome {
	t.Helper()
	sel, err := r.ValidateSelectionWithSession(service, revision, &key)
	if err != nil {
		t.Fatalf("validate select %s key %q: %v", service, key, err)
	}
	return r.Select(sel)
}

// assertPick locks one successful selection's full target triple: instance id,
// current address and the instance's currently accepted health sequence must
// all belong to the same instance chosen for this request.
func assertPick(t *testing.T, out SelectOutcome, id, addr string, seq int64) {
	t.Helper()
	if !out.OK {
		t.Fatalf("select should succeed, got %+v", out)
	}
	if out.InstanceID != id || out.Address != addr || out.Sequence != seq {
		t.Fatalf("select target = %q/%s/seq %d, want %q/%s/seq %d (outcome %+v)",
			out.InstanceID, out.Address, out.Sequence, id, addr, seq, out)
	}
}

// TestRegistryTwoSessionsShareOneRotationAndStayIndependent fixes the
// interleaving contract for two keys in one service. Both keys' first
// successes consume the same rotation in input order; later reuses never move
// it; plain selections continue just after the last instance an actual
// rotation returned; and every result carries the selected instance's own
// address and sequence rather than the other session's.
func TestRegistryTwoSessionsShareOneRotationAndStayIndependent(t *testing.T) {
	r := NewRegistry()
	registerService(t, r, "svc", 0, []Instance{
		{ID: "a", Address: "h1:1"}, {ID: "b", Address: "h2:2"}, {ID: "c", Address: "h3:3"},
	})
	markHealth(t, r, "svc", "a", 1, 1, true, "")
	markHealth(t, r, "svc", "b", 1, 2, true, "")
	markHealth(t, r, "svc", "c", 1, 3, true, "")

	// The first key rotates from the unset position to the smallest id and
	// binds x -> a; the shared cursor rests on a.
	assertPick(t, selectSession(t, r, "svc", 1, "x"), "a", "h1:1", 1)

	// The second key is a different session: the existing x -> a binding must
	// not pick its target. Its first success continues the SAME rotation from
	// the current position, landing on b, and binds y -> b.
	assertPick(t, selectSession(t, r, "svc", 1, "y"), "b", "h2:2", 2)

	// Interleaved reuses return each session's own binding and move nothing.
	assertPick(t, selectSession(t, r, "svc", 1, "x"), "a", "h1:1", 1)
	assertPick(t, selectSession(t, r, "svc", 1, "y"), "b", "h2:2", 2)

	// A plain select continues just after the last rotated id (b), proving the
	// reuses above neither advanced nor rewound the rotation.
	assertPick(t, selected(t, r, "svc", 1), "c", "h3:3", 3)

	// Reusing the earlier-bound instance (a) must not drag a later plain select
	// backwards, and the other session's reuse must not skip a healthy
	// instance: both reuses still answer their own bindings while the cursor
	// stays on c.
	assertPick(t, selectSession(t, r, "svc", 1, "x"), "a", "h1:1", 1)
	assertPick(t, selectSession(t, r, "svc", 1, "y"), "b", "h2:2", 2)

	// Plain rotation wraps past c to a, then continues to b exactly once each:
	// no reuse inserted an extra skip.
	assertPick(t, selected(t, r, "svc", 1), "a", "h1:1", 1)
	assertPick(t, selected(t, r, "svc", 1), "b", "h2:2", 2)

	// Newer accepted observations on the bound instances are reflected per
	// session: x reports a's current record and y reports b's, never a mix.
	markHealth(t, r, "svc", "a", 1, 10, true, "")
	markHealth(t, r, "svc", "b", 1, 20, true, "")
	assertPick(t, selectSession(t, r, "svc", 1, "x"), "a", "h1:1", 10)
	assertPick(t, selectSession(t, r, "svc", 1, "y"), "b", "h2:2", 20)

	// The plain rotation is still where the last real rotation left it (b), so
	// it continues to c and then wraps to a carrying a's latest sequence.
	assertPick(t, selected(t, r, "svc", 1), "c", "h3:3", 3)
	assertPick(t, selected(t, r, "svc", 1), "a", "h1:1", 10)

	// Selections changed neither the revision nor any accepted health record.
	if rev := r.RevisionOf("svc"); rev != 1 {
		t.Fatalf("selection changed the registration revision: %d", rev)
	}
	if inst := instanceHealth(t, r, "svc", "a"); inst.Health != HealthHealthy || inst.Sequence != 10 || inst.Reason != "" {
		t.Fatalf("a accepted record changed by selection: %+v", inst)
	}
	if inst := instanceHealth(t, r, "svc", "b"); inst.Health != HealthHealthy || inst.Sequence != 20 {
		t.Fatalf("b accepted record changed by selection: %+v", inst)
	}
	if inst := instanceHealth(t, r, "svc", "c"); inst.Health != HealthHealthy || inst.Sequence != 3 {
		t.Fatalf("c accepted record changed by selection: %+v", inst)
	}
}

// TestRegistrySessionUnhealthyRebindIsolatesAndMayShare drives one session's
// bound instance unhealthy while another session's instance stays healthy. The
// affected session alone reselects from the current rotation and rewrites only
// its own binding; the two sessions are then allowed to converge on the same
// instance without it being a conflict or stealing the other binding. The
// originally bound instance recovering afterwards does not move the rebound
// session, and a plain select continues from the successful reselection's
// position.
func TestRegistrySessionUnhealthyRebindIsolatesAndMayShare(t *testing.T) {
	r := NewRegistry()
	registerService(t, r, "svc", 0, []Instance{
		{ID: "a", Address: "h1:1"}, {ID: "b", Address: "h2:2"}, {ID: "c", Address: "h3:3"},
	})
	markHealth(t, r, "svc", "a", 1, 1, true, "")
	markHealth(t, r, "svc", "b", 1, 2, true, "")
	markHealth(t, r, "svc", "c", 1, 3, true, "")

	// x -> a, then y -> b; the shared cursor rests on b.
	assertPick(t, selectSession(t, r, "svc", 1, "x"), "a", "h1:1", 1)
	assertPick(t, selectSession(t, r, "svc", 1, "y"), "b", "h2:2", 2)

	// Only a (x's binding) receives a newer unhealthy observation; b and c
	// remain healthy.
	markHealth(t, r, "svc", "a", 1, 4, false, "down")

	// x's next selection cannot reuse a and falls back to the rotation at its
	// current position (just after b), choosing c. Only x's binding moves; the
	// returned triple is c's, never stale data from a.
	assertPick(t, selectSession(t, r, "svc", 1, "x"), "c", "h3:3", 3)

	// y is unaffected: its own binding to b is still returned.
	assertPick(t, selectSession(t, r, "svc", 1, "y"), "b", "h2:2", 2)
	assertPick(t, selectSession(t, r, "svc", 1, "x"), "c", "h3:3", 3)

	// c (now x's binding) turns unhealthy too, leaving b as the sole healthy
	// instance. x's fallback continues just after c, wraps and rebinds to b.
	markHealth(t, r, "svc", "c", 1, 5, false, "down")
	assertPick(t, selectSession(t, r, "svc", 1, "x"), "b", "h2:2", 2)

	// Two different sessions bound to the same instance is allowed: it is not
	// a conflict and neither request displaces the other session's binding.
	assertPick(t, selectSession(t, r, "svc", 1, "y"), "b", "h2:2", 2)
	assertPick(t, selectSession(t, r, "svc", 1, "x"), "b", "h2:2", 2)

	// The original instance a accepts a newer healthy observation and
	// recovers. The session that moved (x) keeps reusing its new binding b;
	// recovery never steals it back. The other session keeps its own binding.
	markHealth(t, r, "svc", "a", 1, 6, true, "")
	assertPick(t, selectSession(t, r, "svc", 1, "x"), "b", "h2:2", 2)
	assertPick(t, selectSession(t, r, "svc", 1, "y"), "b", "h2:2", 2)

	// The plain rotation continues from the position set by x's successful
	// reselection (cursor on b): with a and b healthy it wraps to a, carrying
	// a's recovered sequence rather than restarting at a's old record.
	assertPick(t, selected(t, r, "svc", 1), "a", "h1:1", 6)

	// The plain rotation rewrote no session binding: both sessions still
	// answer b even though the cursor moved through a.
	assertPick(t, selectSession(t, r, "svc", 1, "x"), "b", "h2:2", 2)
	assertPick(t, selectSession(t, r, "svc", 1, "y"), "b", "h2:2", 2)

	// The selections and binding changes left the revision and the accepted
	// health records exactly as the observations set them.
	if rev := r.RevisionOf("svc"); rev != 1 {
		t.Fatalf("selection changed the registration revision: %d", rev)
	}
	if inst := instanceHealth(t, r, "svc", "a"); inst.Health != HealthHealthy || inst.Sequence != 6 || inst.Reason != "" {
		t.Fatalf("a final record: %+v", inst)
	}
	if inst := instanceHealth(t, r, "svc", "b"); inst.Health != HealthHealthy || inst.Sequence != 2 {
		t.Fatalf("b final record: %+v", inst)
	}
	if inst := instanceHealth(t, r, "svc", "c"); inst.Health != HealthUnhealthy || inst.Sequence != 5 || inst.Reason != "down" {
		t.Fatalf("c final record: %+v", inst)
	}
}

// TestRegistryTwoSessionsNoHealthyKeepsBothBindingsAndCursor isolates the
// failure path shared by two sessions: once every instance is unhealthy, keyed
// and plain selections all return no_healthy with the current revision and a
// reason but no fabricated instance, address or sequence. The failures
// preserve both sessions' prior bindings and the shared rotation position.
//
// Recovery is ordered so a surviving binding is distinguishable from a fresh
// rotation: an instance no session is bound to (c) recovers first, then x's
// bound a recovers while the cursor still rests on b. A request that reused
// the preserved binding returns a; one that had lost it would rotate just
// after b to c instead. After y's bound b recovers both sessions reuse their
// own targets with the latest sequences, and a plain select resumes from the
// last real rotation at c rather than anywhere the failures or reuses moved.
func TestRegistryTwoSessionsNoHealthyKeepsBothBindingsAndCursor(t *testing.T) {
	r := NewRegistry()
	registerService(t, r, "svc", 0, []Instance{
		{ID: "a", Address: "h1:1"}, {ID: "b", Address: "h2:2"}, {ID: "c", Address: "h3:3"},
	})
	markHealth(t, r, "svc", "a", 1, 1, true, "")
	markHealth(t, r, "svc", "b", 1, 2, true, "")
	markHealth(t, r, "svc", "c", 1, 3, true, "")

	// x -> a then y -> b; the last real rotation parked the shared cursor on b.
	assertPick(t, selectSession(t, r, "svc", 1, "x"), "a", "h1:1", 1)
	assertPick(t, selectSession(t, r, "svc", 1, "y"), "b", "h2:2", 2)

	// Every instance receives a newer unhealthy observation.
	markHealth(t, r, "svc", "a", 1, 4, false, "down")
	markHealth(t, r, "svc", "b", 1, 5, false, "down")
	markHealth(t, r, "svc", "c", 1, 6, false, "down")

	// Keyed and plain requests all fail the same way: no_healthy at the
	// current revision with a stated reason, inventing neither an instance id
	// nor an address nor a sequence.
	assertNoHealthy := func(key *string) {
		t.Helper()
		var out SelectOutcome
		if key == nil {
			sel, err := r.ValidateSelection("svc", 1)
			if err != nil {
				t.Fatalf("validate plain select: %v", err)
			}
			out = r.Select(sel)
		} else {
			out = selectSession(t, r, "svc", 1, *key)
		}
		if out.OK || out.Kind != OutcomeNoHealthy {
			t.Fatalf("should be no_healthy, got %+v", out)
		}
		if out.Revision != 1 || out.Reason == "" {
			t.Fatalf("no_healthy must state revision and reason, got %+v", out)
		}
		if out.InstanceID != "" || out.Address != "" || out.Sequence != 0 {
			t.Fatalf("no_healthy must fabricate no target, got id=%q addr=%q seq=%d", out.InstanceID, out.Address, out.Sequence)
		}
	}
	keyX, keyY := "x", "y"
	assertNoHealthy(&keyX)
	assertNoHealthy(&keyY)
	assertNoHealthy(nil)

	// An instance no session is bound to recovers first. No keyed request is
	// made against it: it only establishes a healthy rotation candidate past
	// the cursor so a later fresh rotation would not coincide with x's binding.
	markHealth(t, r, "svc", "c", 1, 7, true, "")

	// x's own bound instance a recovers while b is still down. x reuses a
	// directly with its latest sequence: had the failure erased the binding,
	// this would be a first-time rotation from cursor b, which skips past b to
	// c — returning a therefore proves the preserved binding was reused and
	// the rotation never moved.
	markHealth(t, r, "svc", "a", 1, 8, true, "")
	assertPick(t, selectSession(t, r, "svc", 1, "x"), "a", "h1:1", 8)

	// y's bound instance b recovers; y likewise reuses b directly instead of
	// rotating to c, showing its binding survived too.
	markHealth(t, r, "svc", "b", 1, 9, true, "")
	assertPick(t, selectSession(t, r, "svc", 1, "y"), "b", "h2:2", 9)
	assertPick(t, selectSession(t, r, "svc", 1, "x"), "a", "h1:1", 8)

	// The last real rotation is still y's original success on b; all the
	// no_healthy failures and direct reuses left the cursor there. A plain
	// select therefore continues just after b to c, then wraps through a and b
	// using each instance's recovered sequence.
	assertPick(t, selected(t, r, "svc", 1), "c", "h3:3", 7)
	assertPick(t, selected(t, r, "svc", 1), "a", "h1:1", 8)
	assertPick(t, selected(t, r, "svc", 1), "b", "h2:2", 9)

	// The plain rotation rewrote no session binding: both sessions still
	// answer their own targets.
	assertPick(t, selectSession(t, r, "svc", 1, "x"), "a", "h1:1", 8)
